"""HTTP-ish request router with caching and retry."""
import time


class Cache:
    """TTL cache. Stores (value, expires_at)."""

    def __init__(self, ttl_seconds=60):
        self.ttl = ttl_seconds
        self._store = {}

    def get(self, key):
        item = self._store.get(key)
        if item is None:
            return None
        value, expires_at = item
        if time.time() > expires_at:
            del self._store[key]
            return None
        return value

    def set(self, key, value):
        self._store[key] = (value, time.time() + self.ttl)


def _is_retryable(status_code):
    return status_code in (429, 500, 502, 503, 504)


class Router:
    def __init__(self, cache=None, max_retries=3, base_delay_ms=100):
        self.cache = cache or Cache()
        self.max_retries = max_retries
        self.base_delay_ms = base_delay_ms

    def request(self, url, handler):
        cached = self.cache.get(url)
        if cached is not None:
            return cached
        attempt = 0
        while True:
            status, body = handler(url)
            if status == 200:
                self.cache.set(url, body)
                return body
            if not _is_retryable(status) or attempt >= self.max_retries:
                return body  # non-retryable or exhausted: return what we got
            attempt += 1
            time.sleep(self.base_delay_ms * (2 ** (attempt - 1)) / 1000)

